class WireTap<T> {
  private readonly taps = new Set<(copy: T) => void>();
  private readonly queue: T[] = [];
  dropped = 0;                                     // visible loss counter
  constructor(private readonly max = 1024) {}
  attach(t: (copy: Readonly<T>) => void): () => void {
    this.taps.add(t);
    return () => { this.taps.delete(t); };         // removable without touching ends
  }
  forward(msg: T, primary: (m: T) => void): void {
    if (this.taps.size) {
      if (this.queue.length >= this.max) { this.queue.shift(); this.dropped++; }  // drop-oldest
      this.queue.push(structuredClone(msg));       // deep copy, never the live reference
      queueMicrotask(() => this.drain());          // analyzer off the producer's tick
    }
    primary(msg);                                  // original message, unmodified
  }
  private drain(): void {
    let copy: T | undefined;
    while ((copy = this.queue.shift())) for (const t of [...this.taps]) t(copy);
  }
}
